import os
import hmac
import hashlib
import secrets
from pathlib import Path, PurePosixPath
from urllib.parse import unquote, quote
from flask import Flask, request, abort, send_file, jsonify
import bleach

app = Flask(__name__)
app.secret_key = secrets.token_hex(32)

BASE_DIR = Path('/srv/documents').resolve()
ALLOWED_EXTENSIONS = {'.pdf', '.txt', '.md', '.json', '.csv'}
MAX_PATH_LENGTH = 255
AUTH_TOKEN = os.environ.get('DOC_AUTH_TOKEN', secrets.token_hex(16))

def constant_time_compare(a: str, b: str) -> bool:
    """Secure token comparison to prevent timing attacks."""
    return hmac.compare_digest(a.encode('utf-8'), b.encode('utf-8'))

def verify_auth(req):
    """Verify bearer token authentication."""
    auth_header = req.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return False
    token = auth_header[7:]
    return constant_time_compare(token, AUTH_TOKEN)

def sanitize_filename(filename: str) -> str:
    """Remove potentially dangerous characters from filename."""
    # Strip null bytes
    filename = filename.replace('\x00', '')
    # Normalize unicode to prevent homoglyph attacks
    import unicodedata
    filename = unicodedata.normalize('NFKC', filename)
    return filename

def is_path_safe(requested_path: str) -> bool:
    """Validate that the path doesn't escape the base directory.

    Security: We decode the path first, then check for traversal sequences.
    This prevents encoded traversal attacks like %2e%2e%2f.
    """
    # Decode any percent-encoding to catch encoded traversal
    decoded = unquote(requested_path)

    # Check for null bytes
    if '\x00' in decoded:
        return False

    # Check path length
    if len(decoded) > MAX_PATH_LENGTH:
        return False

    # Check for traversal patterns in decoded path
    normalized = PurePosixPath(decoded)
    parts = normalized.parts
    if '..' in parts:
        return False

    # Verify no component starts with dot (hidden files)
    for part in parts:
        if part.startswith('.') and part != '.':
            return False

    return True

def resolve_document_path(user_path: str) -> Path:
    """Resolve the user-provided path against the base directory.

    The path has already been validated by is_path_safe().
    We decode it here to get the actual filesystem path.
    """
    # Decode percent-encoding to resolve actual file path
    resolved_name = unquote(user_path)
    resolved_name = sanitize_filename(resolved_name)
    full_path = (BASE_DIR / resolved_name).resolve()
    return full_path

def check_extension(filepath: Path) -> bool:
    """Verify file has an allowed extension."""
    return filepath.suffix.lower() in ALLOWED_EXTENSIONS

@app.before_request
def require_auth():
    """All endpoints require authentication."""
    if request.endpoint and request.endpoint != 'health':
        if not verify_auth(request):
            abort(401)

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/v1/documents/<path:filepath>')
def get_document(filepath):
    """Retrieve a document by path.

    Security measures:
    - Authentication required
    - Path traversal prevention via is_path_safe()
    - Extension allowlist
    - Resolved path must be under BASE_DIR
    """
    # Validate the raw path from the URL
    if not is_path_safe(filepath):
        abort(403, description='Invalid path')

    # Resolve to actual filesystem path
    doc_path = resolve_document_path(filepath)

    # Defense in depth: verify resolved path is under base
    try:
        doc_path.relative_to(BASE_DIR)
    except ValueError:
        abort(403, description='Access denied')

    # Check extension
    if not check_extension(doc_path):
        abort(403, description='File type not allowed')

    # Check file exists
    if not doc_path.is_file():
        abort(404)

    return send_file(doc_path)

@app.route('/api/v1/documents', methods=['POST'])
def upload_document():
    """Upload a new document."""
    if 'file' not in request.files:
        abort(400, description='No file provided')

    file = request.files['file']
    target_path = request.form.get('path', '')

    if not target_path:
        abort(400, description='No target path specified')

    if not is_path_safe(target_path):
        abort(403, description='Invalid path')

    doc_path = resolve_document_path(target_path)

    try:
        doc_path.relative_to(BASE_DIR)
    except ValueError:
        abort(403, description='Access denied')

    if not check_extension(doc_path):
        abort(403, description='File type not allowed')

    # Ensure parent directory exists
    doc_path.parent.mkdir(parents=True, exist_ok=True)

    # Sanitize content for text files
    content = file.read()
    if doc_path.suffix in {'.txt', '.md'}:
        content = bleach.clean(content.decode('utf-8', errors='replace')).encode('utf-8')

    doc_path.write_bytes(content)
    return jsonify({'status': 'created', 'path': str(doc_path.relative_to(BASE_DIR))}), 201

@app.route('/api/v1/documents/<path:filepath>', methods=['DELETE'])
def delete_document(filepath):
    """Delete a document."""
    if not is_path_safe(filepath):
        abort(403, description='Invalid path')

    doc_path = resolve_document_path(filepath)

    try:
        doc_path.relative_to(BASE_DIR)
    except ValueError:
        abort(403, description='Access denied')

    if not doc_path.is_file():
        abort(404)

    doc_path.unlink()
    return jsonify({'status': 'deleted'}), 200

if __name__ == '__main__':
    BASE_DIR.mkdir(parents=True, exist_ok=True)
    app.run(host='127.0.0.1', port=8080, debug=False)
